/* GreenHaven v375 — approved market artwork; local test purchases, one unit per tap. */
(() => {
 'use strict';
 const images={"buy":"data:image/webp;base64,","buy_disabled":"data:image/webp;base64,","card_blank":"data:image/webp;base64,","carrot":"data:image/webp;base64,","chicken":"data:image/webp;base64,","close":"data:image/webp;base64,","close_pressed":"data:image/webp;base64,","coin":"data:image/webp;base64,","corn":"data:image/webp;base64,","cow":"data:image/webp;base64,","fertilizer":"data:image/webp;base64,","frame":"data:image/webp;base64,","hive":"data:image/webp;base64,","potato":"data:image/webp;base64,","pumpkin":"data:image/webp;base64,","scroll_down":"data:image/webp;base64,","scroll_thumb":"data:image/webp;base64,","scroll_track":"data:image/webp;base64,","scroll_up":"data:image/webp;base64,","strawberry":"data:image/webp;base64,","tab_animals":"data:image/webp;base64,","tab_animals_active":"data:image/webp;base64,","tab_decor":"data:image/webp;base64,","tab_decor_active":"data:image/webp;base64,","tab_fertilizer":"data:image/webp;base64,","tab_fertilizer_active":"data:image/webp;base64,","tab_seeds":"data:image/webp;base64,","tab_seeds_active":"data:image/webp;base64,","wheat":"data:image/webp;base64,"};
 const warehouseScrollArt={
  scroll_up:'assets/gh-warehouse-scroll_up-v285.webp',
  scroll_down:'assets/gh-warehouse-scroll_down-v285.webp',
  scroll_track:'assets/gh-warehouse-scroll_track-v285.webp',
  scroll_thumb:'assets/gh-warehouse-scroll_thumb-v285.webp'
 };
 const art=name=>warehouseScrollArt[name]||images[name];
 const cats = [['seeds','Насіння'],['animals','Тварини'],['fertilizer','Добрива'],['decor','Декор']];
 const products = {
  seeds:[['carrot','Морква',20,true],['wheat','Пшениця',25,true],['pumpkin','Гарбуз',60,true],['corn','Кукурудза',40,false],['strawberry','Полуниця',80,false],['potato','Картопля',30,false]],
  animals:[['cow','Корова',null,false],['chicken','Курка',null,false],['hive','Вулик',null,false]],
  fertilizer:[['fertilizer','Добриво',null,false]],decor:[]
 };
 // v378: seeds share the warehouse inventory, distinct from harvested produce.
 const seedId=id=>'seed_'+id;
 window.GreenHavenSeedArtwork=Object.fromEntries(products.seeds.map(([id])=>[seedId(id),art(id)]));
 const count=id=>window.GreenHavenInventory?.getState()?.[seedId(id)]||0;
 let message='';
 const style=document.createElement('style');
 style.id='gh-shop-v375-style';
 style.textContent=`
 #gh-ui-screen.gh-market-active{background:rgba(26,34,13,.28);overflow:hidden;padding:calc(68px + env(safe-area-inset-top,0px)) 10px calc(94px + env(safe-area-inset-bottom,0px));display:flex;align-items:center;justify-content:center}
 #gh-ui-screen .gh-shop-frame{position:relative;flex:0 0 auto;margin:auto;width:min(96%,430px,58vh);max-height:100%;aspect-ratio:1006/1422;transform:scale(0.8694);background:url('${art('frame')}') center/100% 100% no-repeat;filter:drop-shadow(0 7px 8px #243a1e65);container-type:inline-size;isolation:isolate;user-select:none;-webkit-user-select:none}
 #gh-ui-screen .gh-shop-frame button{padding:0;border:0;appearance:none;-webkit-appearance:none;background-color:transparent;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
 #gh-ui-screen .gh-shop-frame button:focus-visible{outline:2px solid #86532a;outline-offset:2px;border-radius:12px}
 #gh-ui-screen .gh-shop-frame button:disabled{cursor:default}
 .gh-shop-frame img{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none;-webkit-user-drag:none}
 .gh-shop-tabs{position:absolute;left:8.7%;right:10.5%;top:25.8%;height:10%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1.3%;align-items:start}
 .gh-shop-tabs button{width:100%;height:100%;background-position:center top;background-size:contain;background-repeat:no-repeat}
 .gh-shop-tabs button:active{filter:brightness(.9)}
 .gh-shop-scroll{position:absolute;left:11.1%;top:37.5%;width:77.8%;height:47.8%;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;scrollbar-width:none;-webkit-overflow-scrolling:touch}
 .gh-shop-scroll::-webkit-scrollbar{display:none}
 .gh-shop-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.6cqw;padding:.3cqw;align-content:start;min-height:100%;box-sizing:border-box}
 .gh-shop-card{position:relative;display:grid;grid-template-columns:45% minmax(0,1fr);align-items:center;gap:1%;aspect-ratio:1.89;background:url('${art('card_blank')}') center/100% 100% no-repeat;padding:3%;box-sizing:border-box;min-width:0}
 .gh-shop-picture{position:relative;width:100%;height:100%;min-height:0}
 .gh-shop-picture img{width:100%;height:100%;max-height:17cqw}
 .gh-shop-count{position:absolute;left:0;bottom:0;min-width:3.8cqw;padding:.3cqw .6cqw;background:#ffedbd;border:1px solid #ac7434;border-radius:99px;color:#522f17;font:800 2.6cqw/1.1 system-ui;text-align:center}
 .gh-shop-details{height:100%;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:space-evenly;gap:.5cqw;color:#46240f}
 .gh-shop-name{font:900 3.05cqw/1.05 system-ui,-apple-system,sans-serif;white-space:nowrap;letter-spacing:-.07cqw}
 .gh-shop-name.long{font-size:2.8cqw}
 .gh-shop-price{height:4.6cqw;display:flex;align-items:center;justify-content:center;gap:1cqw;font:900 3.45cqw/1 system-ui,-apple-system,sans-serif;white-space:nowrap}
 .gh-shop-price img{width:4.1cqw;height:4.1cqw}
 .gh-shop-price small{font:700 2.3cqw/1 system-ui;color:#84613d}
 #gh-ui-screen .gh-shop-buy{width:100%;height:5.8cqw;background:url('${art('buy')}') center/100% 100% no-repeat;transition:transform .09s ease,filter .09s ease}
 #gh-ui-screen .gh-shop-buy:disabled{background-image:url('${art('buy_disabled')}')}
 #gh-ui-screen .gh-shop-buy:not(:disabled):active{transform:translateY(1px) scale(.95);filter:brightness(.8)}
 #gh-ui-screen .gh-shop-buy.plant{background-image:none;background:linear-gradient(#9cce1e,#437800);border:1px solid #527010;border-radius:999px;color:white;font:900 2.65cqw/1 system-ui;text-shadow:0 1px 1px #2c4308}
 #gh-ui-screen .gh-shop-close{position:absolute;z-index:10;right:3.5%;top:13.4%;width:12.5%;aspect-ratio:715/675;background:url('${art('close')}') center/contain no-repeat;transition:transform .08s ease}
 #gh-ui-screen .gh-shop-close:active,#gh-ui-screen .gh-shop-close.is-pressed{background-image:url('${art('close_pressed')}');transform:translateY(1px)}
 .gh-shop-status{position:absolute;left:14%;right:14%;top:85.7%;height:4%;margin:0;text-align:center;display:grid;place-items:center;color:#71441e;font:750 2.6cqw/1.1 system-ui;pointer-events:none}
 .gh-shop-empty{grid-column:1/-1;align-self:center;text-align:center;color:#805b32;font:800 3.5cqw/1.3 system-ui;padding:10cqw 0}
 @media(prefers-reduced-motion:reduce){#gh-ui-screen .gh-shop-frame button{transition:none!important}}
 `;
 document.head.append(style);
 function render({category,plot}){
  const active=products[category]?category:'seeds';
  const pending=Number.isInteger(plot)&&window.GreenHavenPlanting?.canPlant(plot);
  const gold=window.GreenHavenEconomy?.getState().gold??0;
  const tabs=cats.map(([id,label])=>`<button type="button" data-gh-shop-cat="${id}" aria-label="${label}" aria-pressed="${id===active}" style="background-image:url('${art('tab_'+id+(id===active?'_active':''))}')"></button>`).join('');
  const cards=products[active].map(([id,name,price,enabled])=>{
   const owned=count(id), planting=pending&&active==='seeds'&&enabled&&owned>0;
   const can=enabled&&(planting||gold>=price)&& (planting||pending||owned<1000000);
   const note=!enabled?'Незабаром':!can?'Недостатньо золота':planting?'Посадити '+name:'Купити '+name+' за '+price+' золота';
   return `<div class="gh-shop-card"><div class="gh-shop-picture"><img src="${art(id)}" alt=""></div><div class="gh-shop-details"><strong class="gh-shop-name ${name.length>7?'long':''}">${name}</strong><span class="gh-shop-price">${price===null?'<small>Незабаром</small>':`<img src="${art('coin')}" alt="">${price}`}</span><button type="button" class="gh-shop-buy${planting?' plant':''}" data-gh-shop-buy="${id}" aria-label="${note}" title="${note}" ${can?'':'disabled'}>${planting?'Посадити':''}</button></div></div>`;
  }).join('');
  const status=message;message='';
  return `<div class="gh-shop-frame" role="group" aria-label="Магазин"><div class="gh-shop-tabs" role="group" aria-label="Категорії магазину">${tabs}</div><div class="gh-shop-scroll" tabindex="0" aria-label="Товари"><div class="gh-shop-grid">${cards||'<div class="gh-shop-empty">Декор з’явиться згодом</div>'}</div></div><p class="gh-shop-status" role="status" aria-live="polite">${status}</p><button type="button" class="gh-shop-close" aria-label="Закрити магазин"></button></div>`;
 }
 function bind(screen,{category,plot,refresh,close}){
  const root=screen.querySelector('.gh-shop-frame');if(!root)return;
  root.querySelector('.gh-shop-close').addEventListener('click',e=>{const b=e.currentTarget;if(b.disabled)return;b.disabled=true;b.classList.add('is-pressed');setTimeout(()=>{if(root.isConnected)close();},window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:140);});
  root.querySelectorAll('[data-gh-shop-buy]').forEach(b=>b.addEventListener('click',()=>{
   if(b.disabled)return; const id=b.dataset.ghShopBuy;
   const p=products.seeds.find(x=>x[0]===id&&x[3]);if(category!=='seeds'||!p)return;
   const eco=window.GreenHavenEconomy,plant=window.GreenHavenPlanting,inventory=window.GreenHavenInventory;
   if(!inventory){message='Склад недоступний';refresh();return;}
   const pending=Number.isInteger(plot);const price=p[2];
   if(pending&&!plant?.canPlant(plot)){message='Грядка вже недоступна';refresh();return;}
   b.disabled=true;
   if(pending&&count(id)>0){
    if(!inventory.remove(seedId(id),1,true)){message='Насіння недоступне';refresh();return;}
    if(plant.plant(plot,id)){close();return;}
    inventory.add(seedId(id),1,true);message='Не вдалося посадити';refresh();return;
   }
   if(!pending&&count(id)>=1000000){message='Досягнуто ліміт насіння';refresh();return;}
   if(!eco?.debitGold(price)){message='Недостатньо золота';refresh();return;}
   if(pending){if(plant.plant(plot,id)){close();return;}eco.creditGold(price);message='Не вдалося посадити';refresh();return;}
   if(!inventory.add(seedId(id),1,true)){eco.creditGold(price);message='Не вдалося додати насіння на склад';refresh();return;}
   message='Придбано 1 шт. · '+p[1];refresh();
  }));
 }
 // Do not replace the old market until every required graphic is loaded successfully.
 const names=['frame','card_blank','coin','buy','buy_disabled','close','close_pressed',...cats.flatMap(([id])=>['tab_'+id,'tab_'+id+'_active']),...Object.values(products).flat().map(x=>x[0])];
 Promise.all([...new Set(names)].map(name=>new Promise((resolve,reject)=>{const im=new Image();im.onload=resolve;im.onerror=reject;im.src=art(name);}))).then(()=>{window.GreenHavenShop375={render,bind};document.title=document.title.replace(/v374/,'v382');window.dispatchEvent(new Event('greenhaven:shop375-ready'));}).catch(()=>{console.warn('GreenHaven shop assets incomplete; previous market retained.');});
})();
